// 金額と通貨を表す record。コンパクトコンストラクタで検証する
// ここを変えてみよう:b の金額を 101 に / 最後の new Money の金額を 0 に
record Money(long amount, String currency) {
    public Money {   // 引数リストを書かないのがコンパクトコンストラクタ
        if (amount < 0) {
            throw new IllegalArgumentException("金額が負: " + amount);
        }
    }
    Money add(Money other) {   // 自分は変えずに新しい Money を返す
        return new Money(amount + other.amount, currency);
    }
}

