// 注文一覧をステータス別に数える
// ここを変えてみよう:orders に注文を足す / EnumMap を HashMap に変えて並び順を比べる
import java.util.*;

enum OrderStatus { ORDERED, SHIPPED, DELIVERED, CANCELLED }
record Order(String id, OrderStatus status) {}

var orders = List.of(
        new Order("A-001", OrderStatus.SHIPPED),
        new Order("A-002", OrderStatus.ORDERED),
        new Order("A-003", OrderStatus.CANCELLED),
        new Order("A-004", OrderStatus.ORDERED));

Map<OrderStatus, Integer> count = new EnumMap<>(OrderStatus.class);
for (Order o : orders) {
    count.merge(o.status(), 1, Integer::sum);
}
System.out.println(count);   // 宣言順に並ぶ

// enum は == で比べてよい(各定数はインスタンスが1つだけ)
long active = orders.stream().filter(
        o -> o.status() != OrderStatus.CANCELLED).count();
System.out.println("キャンセル以外: " + active + "件");

